function polarToCartesian(cx, cy, r, angleDeg) {
  const rad = (angleDeg * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy - r * Math.sin(rad) };
}

/* Radial ring gauge. A full circle rather than a semicircle: nothing clips at the
   edges, the numeral sits at true centre, and the caption lives in HTML below the
   SVG so it can never collide with the stroke. */
function RiskGauge({ pct, size }) {
  const R = 76, SW = 16, C = 100;
  const circ = 2 * Math.PI * R;
  const clamped = Math.max(0, Math.min(100, pct));
  const filled = (clamped / 100) * circ;
  const color = riskColor(clamped);

  return (
    <div className="gauge-wrap" style={{ width: size + "px" }}>
      <svg viewBox="0 0 200 200" className="risk-gauge" role="img"
        aria-label={clamped.toFixed(0) + " percent chance of progressing"}>
        <circle cx={C} cy={C} r={R} fill="none" stroke="var(--border)" strokeWidth={SW} />
        <circle
          key={clamped}
          className="gauge-arc"
          cx={C} cy={C} r={R} fill="none" stroke={color} strokeWidth={SW} strokeLinecap="round"
          transform={"rotate(-90 " + C + " " + C + ")"}
          style={{ strokeDasharray: filled + " " + (circ - filled), strokeDashoffset: circ, animationDuration: "0.9s" }}
        />
        <text x={C} y={C - 4} textAnchor="middle" dominantBaseline="central"
          fontSize="52" fontWeight="700" fill={color}
          fontFamily="Geist Mono, ui-monospace, monospace" className="gauge-value">
          {clamped.toFixed(0)}
        </text>
        <text x={C} y={C + 30} textAnchor="middle" dominantBaseline="central"
          fontSize="15" fontWeight="600" fill={color} opacity="0.75"
          fontFamily="Geist Mono, ui-monospace, monospace">%</text>
      </svg>
      <div className="gauge-caption-below" style={{ color }}>{riskWord(clamped)} risk</div>
      <div className="gauge-sublabel">of progressing further</div>
    </div>
  );
}

