/* In-app confirmation dialog. window.confirm() is blocked inside sandboxed
   iframes, so all destructive actions route through this instead. */
/* ---------------------------------------------------------------
   Persistence layer. Records, the patient index, and the in-progress
   session all live in window.storage (browser-local).
--------------------------------------------------------------- */
const PATIENT_INDEX_KEY = "patients:index";
const SESSION_KEY = "session:current";
const BLANK_DRAFT = {
  patientId: "", patientName: "",
  egfr: "", age: "", sbp: "", bmi: "",        // numerics start empty, not at a default
  sex: "", diabetes: "",                      // categoricals start unset
  upcr: "",                                   // UPCR in g/gCr (Qin scale)
  steps: 6,
};

/* Every clinical field the model needs before it can compute. */
const REQUIRED_FIELDS = [
  { key: "egfr", label: "eGFR" },
  { key: "sbp", label: "Systolic BP" },
  { key: "age", label: "Age" },
  { key: "sex", label: "Sex" },
  { key: "diabetes", label: "Diabetes" },
  { key: "upcr", label: "UPCR" },
];

function missingFields(d) {
  return REQUIRED_FIELDS.filter((f) => d[f.key] === "" || d[f.key] === null || d[f.key] === undefined);
}

/* Numeric fields may be blank, so every read is coerced before it reaches the model. */
function num(v, fallback) {
  const n = typeof v === "number" ? v : parseFloat(v);
  return isNaN(n) ? fallback : n;
}

/* Storage abstraction: window.storage is a Claude-artifact-only API that does
   NOT exist when this file is run standalone (VS Code, a local dev server, a
   real deployment) -- every direct window.storage.get/set call would throw
   there and nothing would ever save. These two wrappers use window.storage
   when it's actually present, and transparently fall back to the browser's
   own localStorage otherwise, so the same code persists data correctly in
   both contexts without any other function needing to change. */
async function storageGet(key) {
  const hasArtifactStorage = typeof window !== "undefined" && window.storage && typeof window.storage.get === "function";
  if (hasArtifactStorage) {
    try { return await window.storage.get(key, false); }
    catch (e) { return null; }
  }
  try {
    const raw = window.localStorage.getItem(key);
    return raw === null ? null : { key, value: raw };
  } catch (e) { return null; }
}

async function storageSet(key, value) {
  const hasArtifactStorage = typeof window !== "undefined" && window.storage && typeof window.storage.set === "function";
  if (hasArtifactStorage) {
    try { return await window.storage.set(key, value, false); }
    catch (e) { return null; }
  }
  try {
    window.localStorage.setItem(key, value);
    return { key, value };
  } catch (e) { return null; }
}

async function readJSON(key, fallback) {
  try {
    const res = await storageGet(key);
    if (res && res.value) return JSON.parse(res.value);
  } catch (e) { /* key absent */ }
  return fallback;
}

/* Same read, but distinguishes "key genuinely has no data" from "the read
   itself failed" (network hiccup, storage not ready yet, malformed JSON).
   Used only on the two user-facing screens where that distinction matters —
   showing "no patients yet" when the real answer is "the read failed" is
   exactly what makes saved data look like it vanished. */
async function readJSONWithStatus(key, fallback) {
  try {
    const res = await storageGet(key);
    if (res && res.value) return { ok: true, value: JSON.parse(res.value) };
    return { ok: true, value: fallback };
  } catch (e) {
    return { ok: false, value: fallback, error: e };
  }
}

async function loadPatientIndex() {
  const idx = await readJSON(PATIENT_INDEX_KEY, []);
  return Array.isArray(idx) ? idx : [];
}

async function upsertPatientIndex(entry) {
  try {
    const idx = await loadPatientIndex();
    const i = idx.findIndex((p) => p.id === entry.id);
    if (i >= 0) idx[i] = { ...idx[i], ...entry };
    else idx.push(entry);
    await storageSet(PATIENT_INDEX_KEY, JSON.stringify(idx));
    return true;
  } catch (e) { return false; }
}

async function loadAssessmentHistory(patientId) {
  const recs = await readJSON("records:" + patientId, []);
  return Array.isArray(recs) ? recs : [];
}

async function saveAssessmentRecord(record) {
  try {
    const key = "records:" + record.patientId;
    const list = await loadAssessmentHistory(record.patientId);
    list.push(record);
    const result = await storageSet(key, JSON.stringify(list));
    await upsertPatientIndex({
      id: record.patientId, name: record.patientName || "",
      lastVisit: record.timestamp, lastRisk: record.riskPct, lastStage: record.stage,
      visits: list.length,
    });
    return !!result;
  } catch (e) { return false; }
}

async function deleteAssessmentRecord(patientId, timestamp) {
  try {
    const list = await loadAssessmentHistory(patientId);
    const next = list.filter((r) => r.timestamp !== timestamp);
    await storageSet("records:" + patientId, JSON.stringify(next));
    const latest = next.length ? next.reduce((a, b) => (a.timestamp > b.timestamp ? a : b)) : null;
    await upsertPatientIndex({
      id: patientId,
      lastVisit: latest ? latest.timestamp : null,
      lastRisk: latest ? latest.riskPct : null,
      lastStage: latest ? latest.stage : null,
      visits: next.length,
    });
    return next;
  } catch (e) { return null; }
}

async function exportAllRecords() {
  const idx = await loadPatientIndex();
  const out = { app: "NephroPath", exportedAt: new Date().toISOString(), patients: [] };
  for (const p of idx) {
    const recs = await loadAssessmentHistory(p.id);
    out.patients.push({ ...p, records: recs });
  }
  return out;
}

async function importAllRecords(parsed) {
  if (!parsed || !Array.isArray(parsed.patients)) throw new Error("Unrecognised backup file");
  let merged = 0;
  for (const p of parsed.patients) {
    if (!p.id) continue;
    const existing = await loadAssessmentHistory(p.id);
    const byTs = new Map(existing.map((r) => [r.timestamp, r]));
    for (const r of (p.records || [])) {
      if (!byTs.has(r.timestamp)) { byTs.set(r.timestamp, r); merged++; }
    }
    const list = Array.from(byTs.values()).sort((a, b) => a.timestamp - b.timestamp);
    await storageSet("records:" + p.id, JSON.stringify(list));
    const latest = list.length ? list[list.length - 1] : null;
    await upsertPatientIndex({
      id: p.id, name: p.name || "",
      lastVisit: latest ? latest.timestamp : null,
      lastRisk: latest ? latest.riskPct : null,
      lastStage: latest ? latest.stage : null,
      visits: list.length,
    });
  }
  return merged;
}

function downloadJSON(data, filename) {
  try {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
    return true;
  } catch (e) { return false; }
}

/* Session persistence — survives a refresh mid-assessment. */
async function saveSession(state) {
  try { await storageSet(SESSION_KEY, JSON.stringify(state)); } catch (e) { /* non-fatal */ }
}
async function loadSession() { return await readJSON(SESSION_KEY, null); }

/* ---------------------------------------------------------------
   Motion primitives. One easing family, one stagger rhythm.
   Everything below obeys the locked motion language.
--------------------------------------------------------------- */
function useInView(opts) {
  const ref = React.useRef(null);
  const [seen, setSeen] = useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") { setSeen(true); return; }
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) { setSeen(true); io.disconnect(); } });
    }, opts || { threshold: 0.12 });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, seen];
}

/* Entrance: fade + rise. Stagger via index, 70ms cascade. */
function Reveal({ children, i, className }) {
  const [ref, seen] = useInView();
  return (
    <div ref={ref}
      className={"reveal " + (seen ? "reveal-in " : "") + (className || "")}
      style={{ transitionDelay: (i || 0) * 70 + "ms" }}>
      {children}
    </div>
  );
}

