/* Canvas filtration field: blood cells drifting through the nephron network behind the
   hero. Runs outside React state (rAF only) so it never re-renders the tree. */
function FiltrationField() {
  const canvasRef = React.useRef(null);
  React.useEffect(() => {
    const cv = canvasRef.current;
    if (!cv) return;
    const reduce = typeof window !== "undefined" && window.matchMedia
      && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const ctx = cv.getContext("2d");
    let raf, w = 0, h = 0;
    const DPR = Math.min(window.devicePixelRatio || 1, 2);

    const resize = () => {
      w = cv.clientWidth; h = cv.clientHeight;
      cv.width = w * DPR; cv.height = h * DPR;
      ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    };
    resize();
    window.addEventListener("resize", resize);

    const N = 70;
    const cells = Array.from({ length: N }, () => ({
      x: Math.random() * w, y: Math.random() * h,
      r: 1.2 + Math.random() * 2.6,
      sp: 0.12 + Math.random() * 0.42,
      amp: 12 + Math.random() * 34,
      ph: Math.random() * Math.PI * 2,
      a: 0.12 + Math.random() * 0.4,
    }));

    let t = 0;
    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      // faint vessel arcs
      ctx.lineWidth = 1;
      for (let i = 0; i < 5; i++) {
        const y = (h / 6) * (i + 1);
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.bezierCurveTo(w * 0.3, y - 40, w * 0.7, y + 40, w, y);
        ctx.strokeStyle = "rgba(122,168,255,0.10)";
        ctx.stroke();
      }
      for (const c of cells) {
        c.x += c.sp;
        if (c.x > w + 20) { c.x = -20; c.y = Math.random() * h; }
        const y = c.y + Math.sin(t * 0.012 + c.ph) * c.amp * 0.25;
        ctx.beginPath();
        ctx.arc(c.x, y, c.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(150,190,255," + c.a + ")";
        ctx.fill();
      }
      t += 1;
      raf = requestAnimationFrame(draw);
    };

    if (reduce) { draw(); cancelAnimationFrame(raf); }
    else raf = requestAnimationFrame(draw);

    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize", resize); };
  }, []);
  return <canvas ref={canvasRef} className="field-canvas" aria-hidden="true" />;
}

/* Numeral that counts up once it scrolls into view. */
function CountUp({ to, suffix, duration }) {
  const [ref, seen] = useInView({ threshold: 0.4 });
  const [val, setVal] = useState(0);
  React.useEffect(() => {
    if (!seen) return;
    const reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) { setVal(to); return; }
    const dur = duration || 1100;
    const t0 = performance.now();
    let raf;
    const tick = (now) => {
      const p = Math.min(1, (now - t0) / dur);
      const eased = 1 - Math.pow(1 - p, 3);          // matches the decelerate family
      setVal(Math.round(to * eased));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [seen, to]);
  return <span ref={ref}>{val}{suffix || ""}</span>;
}

/* Headline that assembles word by word. Kinetic type, one cascade, no loop. */
function SplitWords({ text, className, delay }) {
  const words = text.split(" ");
  const [ref, seen] = useInView({ threshold: 0.2 });
  return (
    <span ref={ref} className={className}>
      {words.map((w, i) => (
        <span key={i} className="word-mask">
          <span className={"word " + (seen ? "word-in" : "")}
            style={{ transitionDelay: (delay || 0) + i * 60 + "ms" }}
            dangerouslySetInnerHTML={{ __html: w + "&nbsp;" }} />
        </span>
      ))}
    </span>
  );
}

/* The one hero moment: the kidney degrades as the reader scrolls the stage list.
   Motion carries meaning here — it *is* the disease progressing. */
function ProgressionScroll() {
  const [active, setActive] = useState(0);
  const stops = React.useRef([]);

  React.useEffect(() => {
    if (typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) setActive(Number(e.target.dataset.idx));
      });
    }, { rootMargin: "-45% 0px -45% 0px", threshold: 0 });
    stops.current.forEach((el) => el && io.observe(el));
    return () => io.disconnect();
  }, []);

  const st = STAGES[active];
  const COPY = [
    "Both kidneys filter around 180 litres of blood a day. At this stage the work is invisible and complete.",
    "Filtration slips slightly. Nothing is felt, nothing shows on a routine day — only a blood test reveals it.",
    "A third of function is gone. This is usually the first stage anyone notices, and the first worth acting on.",
    "Waste begins to accumulate faster than it clears. Fatigue, swelling and blood pressure become harder to manage.",
    "Function is severely reduced. Preparation for dialysis or transplant normally begins here, before it is urgent.",
    "The kidneys can no longer sustain the body alone. Treatment replaces the organ rather than protecting it.",
  ];

  return (
    <section className="prog">
      <div className="prog-inner">
        <div className="prog-sticky">
          <div className="prog-stage-mark" style={{ color: st.color }}>{st.code}</div>
          <KidneyStatus stageIdx={active} size={300} />
          <div className="prog-meter">
            {STAGES.map((x, i) => (
              <span key={x.code} className={"prog-tick " + (i <= active ? "prog-tick-on" : "")}
                style={i <= active ? { background: x.color } : {}} />
            ))}
          </div>
          <div className="prog-fn">
            {Math.round(((STAGES.length - active) / STAGES.length) * 100)}% function remaining
          </div>
        </div>

        <div className="prog-track">
          <h2 className="prog-title">How it progresses</h2>
          <p className="prog-lede">Scroll or tap a stage to follow the loss of function.</p>
          {STAGES.map((x, i) => (
            <div key={x.code} ref={(el) => (stops.current[i] = el)} data-idx={i}
              className={"prog-stop " + (i === active ? "prog-stop-on" : "")}
              onClick={() => setActive(i)} role="button" tabIndex={0}
              onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") setActive(i); }}>
              <div className="prog-stop-head">
                <span className="prog-stop-code" style={{ color: x.color }}>{x.code}</span>
                <span className="prog-stop-range">{x.range} mL/min</span>
              </div>
              <div className="prog-stop-name">{x.name}</div>
              <p className="prog-stop-copy">{COPY[i]}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

/* ---------------------------------------------------------------
   App Verification: proves the running engine reproduces the finalized
   workbook (NEPHROPATH_CPT_RECONSTRUCTED_v1_3) rather than assuming the
   ported equations are correct. Compares Excel-expected vs. app-computed
   for every cell of all six columns, across all three reference profiles.
--------------------------------------------------------------- */
function runVerification() {
  const TOL = 1e-6;
  const rows = [];
  let maxDiff = 0;
  for (const c of VALIDATION_CASES) {
    const gotStageIdx = stageIndexFromEGFR(c.p.egfr);
    const stageMatch = STAGES[gotStageIdx].code === c.stage;
    const T = buildMatrix(c.p);
    for (let ci = 0; ci < STAGES.length; ci++) {
      const cur = STAGES[ci].code;
      for (let ri = 0; ri < STAGES.length; ri++) {
        const nxt = STAGES[ri].code;
        const expected = c.expected[cur][ri];
        const got = T[ci][ri];
        const diff = Math.abs(expected - got);
        maxDiff = Math.max(maxDiff, diff);
        rows.push({ profile: c.name, stageOk: stageMatch, current: cur, next: nxt, expected, got, diff, pass: diff <= TOL });
      }
    }
  }
  const passCount = rows.filter((r) => r.pass).length;
  return { rows, passCount, total: rows.length, maxDiff, tol: TOL };
}

function VerificationScreen() {
  const result = useMemo(() => runVerification(), []);
  const [openProfile, setOpenProfile] = useState("Reference");
  const allPass = result.passCount === result.total;
  const grouped = VALIDATION_CASES.map((c) => ({
    name: c.name, p: c.p, stage: c.stage,
    rows: result.rows.filter((r) => r.profile === c.name),
  }));

  return (
    <div className="screen">
      <div className="screen-head">
        <h1 className="screen-title">App verification</h1>
        <p className="screen-sub">
          Excel expected value vs. app-computed value, for every current-state → next-state
          cell, across all three profiles defined in the finalized workbook.
        </p>
      </div>

      <div className={"verify-summary " + (allPass ? "verify-pass" : "verify-fail")}>
        {allPass ? <CheckCircle2 size={22} /> : <XCircle size={22} />}
        <div className="verify-summary-text">
          <div className="verify-summary-title">
            {result.passCount}/{result.total} comparisons pass
          </div>
          <div className="verify-summary-sub">
            tolerance {result.tol.toExponential(0)} · maximum |difference| = {result.maxDiff.toExponential(3)}
          </div>
        </div>
      </div>

      <div className="verify-profiles">
        {grouped.map((g) => {
          const pass = g.rows.filter((r) => r.pass).length;
          const open = openProfile === g.name;
          return (
            <div key={g.name} className="verify-profile">
              <button className="verify-profile-head" onClick={() => setOpenProfile(open ? null : g.name)}>
                <span className="verify-profile-name">{g.name}</span>
                <span className="verify-profile-meta">
                  eGFR {g.p.egfr} → {g.stage} · {g.p.age}y {g.p.sex} · SBP {g.p.sbp} · UPCR {g.p.upcr} · BMI {g.p.bmi}
                </span>
                <span className={"verify-profile-badge " + (pass === g.rows.length ? "badge-pass" : "badge-fail")}>
                  {pass}/{g.rows.length}
                </span>
              </button>
              {open && (
                <div className="verify-table-wrap">
                  <table className="verify-table">
                    <thead>
                      <tr><th>Current</th><th>Next</th><th>Excel expected</th><th>App value</th><th>|diff|</th><th></th></tr>
                    </thead>
                    <tbody>
                      {g.rows.map((r, i) => (
                        <tr key={i} className={r.pass ? "" : "verify-row-fail"}>
                          <td>{r.current}</td>
                          <td>{r.next}</td>
                          <td className="mono">{r.expected.toFixed(6)}</td>
                          <td className="mono">{r.got.toFixed(6)}</td>
                          <td className="mono">{r.diff.toExponential(2)}</td>
                          <td>{r.pass ? <CheckCircle2 size={13} className="verify-ok" /> : <XCircle size={13} className="verify-bad" />}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div className="verify-note">
        Runs the same engine that powers Result and In-depth against three real, held-out
        CKD-ROUTE patients from the audited refined-model workbook (never used to fit the
        coefficients above) — 6 current states × 6 next states × 3 profiles = 108
        comparisons, computed live in this browser, not cached.
      </div>
    </div>
  );
}

